"""A requirement states the same thing in the test plan and in the matrix.

Covers `MQC_CMN_UNI_112382`, inventoried in
``docs/design/cmn_verdict_and_cli.md`` section 10.

A failure here is **not a model finding**, so the module carries no priority
marker.
"""

# ------------------------------------------------------------- cases in here
# Generated by `tools/refresh_case_summaries.py`.
#
# TestMQCRequirementStatements
#   112382  a_requirement_stated_two_ways_is_reported
# ------------------------------------------------------------ end of cases

from pathlib import Path

import pytest

from cmn.traceability import statement_problems

pytestmark = pytest.mark.unit

_ROOT = Path(__file__).resolve().parents[2]


class TestMQCRequirementStatements:
    """One statement per requirement, wherever it is written."""

    def MQC_CMN_UNI_112382_a_requirement_stated_two_ways_is_reported(
        self, tmp_path: Path
    ) -> None:
        """A statement differing between plan and matrix is reported.

        A coverage table listing the same identifier with a dimension in its
        second column is not a statement and is not compared, and backticks
        are ignored.

        Design: ``cmn_verdict_and_cli.md`` section 10.17.1.

        Args:
            tmp_path (Path): Where the constructed plan and matrix are written.

        Returns:
            None
        """
        plan = tmp_path / "plan.md"
        plan.write_text(
            "| ID | Requirement | Source |\n|---|---|---|\n"
            "| `MQC_REQ_HAR_CMN_0001` | A run reads `--tests` once | here |\n"
            "| `MQC_REQ_HAR_CMN_0002` | An old statement | here |\n\n"
            "| Requirement | Axis varied |\n|---|---|\n"
            "| `MQC_REQ_HAR_CMN_0001` | Delivery of the request |\n",
            encoding="utf-8",
        )
        matrix = tmp_path / "rtm.csv"
        matrix.write_text(
            "requirement_id,requirement_text,source,category,test_ids,notes\n"
            "MQC_REQ_HAR_CMN_0001,A run reads --tests once,self-authored,here,,\n"
            "MQC_REQ_HAR_CMN_0002,The current statement,self-authored,here,,\n",
            encoding="utf-8",
        )

        reported = statement_problems(plan, matrix)
        assert len(reported) == 1 and "MQC_REQ_HAR_CMN_0002" in reported[0], reported

        assert not statement_problems(
            _ROOT / "docs" / "testing" / "harness_test_plan.md",
            _ROOT / "docs" / "testing" / "rtm_harness.csv",
        ), "the harness plan and matrix state a requirement differently"
